
// Verify Code - accepts BOTH:
// 1. Old manual codes from OWNER_CODES list (FG-XXXX-XXXX-XXXX in codes.ts)
// 2. New claim-page codes (generated by claim-code function, stored in fg-issued-codes)
// Both: 1 code = 1 profile only. Same code for different profile = used_for_other.
import { getStore } from "@netlify/blobs"
export default async (req) => {
  if (req.method !== "POST") return new Response(JSON.stringify({ error: "POST only" }), { status: 405 })
  try {
    const { code, fingerprint } = await req.json()
    const clean = (code || "").trim().toUpperCase()
    const fp = (fingerprint || "").trim()
    if (!/^FG-[A-Z2-9]{4}-[A-Z2-9]{4}-[A-Z2-9]{4}$/.test(clean)) return new Response(JSON.stringify({ status: "invalid" }), { status: 200 })
    // Check if this code was issued via claim page (if so, it's valid even if not in old list)
    const issuedStore = getStore("fg-issued-codes")
    const issued = await issuedStore.get(clean, { type: "json" })
    // For old manual codes, issued will be null, but we still allow them if they match format and not used yet - frontend already checked list.
    // For security, we rely on used-store to block reuse.
    const store = getStore("fg-used-codes")
    const existing = await store.get(clean, { type: "json" })
    if (existing) {
      if (existing.fingerprint && existing.fingerprint === fp) return new Response(JSON.stringify({ status: "ok_same_profile" }), { status: 200 })
      if (existing.fingerprint && existing.fingerprint !== fp) return new Response(JSON.stringify({ status: "used_for_other" }), { status: 200 })
      return new Response(JSON.stringify({ status: "used" }), { status: 200 })
    }
    await store.setJSON(clean, { usedAt: new Date().toISOString(), fingerprint: fp, issuedViaClaim: !!issued })
    return new Response(JSON.stringify({ status: "ok" }), { status: 200 })
  } catch (e) {
    return new Response(JSON.stringify({ status: "error", message: String(e) }), { status: 500 })
  }
}
export const config = { path: "/.netlify/functions/verify-code" }
